#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H(h)(cos((h)*6.3+vec3(0,23,21))*.5+.5)
#define PI 3.14159265359

vec3 palette(float t, vec3 color1, vec3 color2, vec3 color3, vec3 color4) {
    return color1 + color2 * cos(2.0 * PI * (color3 * t + color4));
}
vec3 function1(vec2 uv, vec2 fragCoord, float time, float fn1, float fn2, float f3, float scale) {
    float f1 = sin(time*1.)*0.004+0.005;
    float f2 = fn1*sin(time*1.1)*32. + 20.;
    float l = length(uv.xy - 0.5);
    float d1 = f3*sin(-time*5. + f2*l);
    float d2 = float(( int( scale* fragCoord.x ) ^ int(scale * fragCoord.y) ) & 4)+fn2;
    float d3 = float(( int( scale* fragCoord.x + uv.x*d1) ^ int(scale * fragCoord.y + time*1. * d1*f1) ) & 4);
    float d4 = float(( int( scale* fragCoord.x) ^ int(scale * fragCoord.y + time*1. * d1*f1) ) & 4);
    float r = 0.1*(mod(d1,d2)*d3);
    float g = l;
    float b = (d4);
    return vec3(r,g,b);
}
vec3 fractal(vec2 p) {
    vec2 pos=p;


    float d, ml=100.;
    vec2 mc=vec2(100.)
    ;

    p=abs(fract(p*0.21)-.5);
    vec2 c=p;

    for(int i=0;i<10;i++) {

        d=dot(p,p);
        p=abs(p+1.)-abs(p-1.)-p;

    	p=p*-1.05/clamp(d,0.25,1.)-c;
        mc=min(mc,abs(p));
        if (i>2) ml=min(ml*(1.+float(i)*.1+cos(iTime)*0.21),abs(p.y-.5));
    }
    mc=max(vec2(0.),1.-mc);
    mc=normalize(mc)*.8;
    ml=pow(max(0.,1.-ml),6.);
    return vec3(mc,d*.4)*ml*(step(0.17,fract(d*.1+iTime*.0+pos.x*.2)))-ml*.1;
}

void mainImage(out vec4 O, vec2 C)
{
    O=vec4(0);
    vec3 n1,p,q,r=iResolution,
    d=normalize(vec3((C*2.-r.xy)/r.y,1)); 
     vec2 uv = C / iResolution.xy;
     float aspect = iResolution.x / iResolution.y;
    uv = (uv - 0.5) * vec2(aspect, 1.0) + 0.5;
    uv.x+=cos(iTime)*0.6;
    uv.y+=sin(iTime)*0.6;
vec3 c22 = fractal(vec2(-100.,100.));
    float time = iTime * 0.05;
 vec3 f1 = function1(uv, C, 200. + iTime*0.1, 10.5, 5., 1.1, 0.1);
    vec3 sumColor = vec3(0.0);
    float sumWeights = 0.0;

    // Number of lights
    float amount = 8.0;

    for (float i = 1.0; i <= amount; i += 1.0) {
        // Oscillation with noise-based modulation
        float oscillationX = sin(time + i * PI * 0.25) * 0.3 + 0.1 * cos(time * i);
        float oscillationY = sin(time + i * PI * 0.5) * 0.4 + 0.1 * sin(time * i * 0.5);
        vec2 initPos = vec2(0.5, 0.5);
        vec2 lightPos = initPos + vec2(oscillationX, oscillationY);

        float lightDist = length(uv - lightPos);

        // Dynamic palette with time modulation
        vec3 color = palette(
            lightDist * i / amount + sin(time + i) * 0.1, 
            vec3(0.570, 0.470, 0.590), 
            vec3(0.632, 0.385, 0.634), 
            vec3(0.520, 0.800, 0.520), 
            vec3(-0.430, -0.397, -0.083)
        );

        // Dynamic weight modulation for more intricate patterns
        float lightWeight = 1.0 / lightDist;
        lightWeight *= sin(time - lightDist * 40.0 * PI);
        lightWeight /= (1.0 + sin(iTime - lightDist * PI * 0.5 * (i / amount)) * 0.5);

        sumColor += lightWeight * color;
        sumWeights += lightWeight;
    }

    sumColor = sumColor / sumWeights; // Normalize color
    sumColor = pow(sumColor, vec3(1.0 / 2.2)); // Gamma correction
    for(float i=0.,a,s,e,g=0.;
        ++i<70.;
        O.xyz+=mix(vec3(1),H(g*.1),.8)*3./e/8e3
    )
    {
     float snd = 2.6-.45*(2.+texture(iChannel0, vec2(clamp(i/100.,0.,.3),0.)).r);
        p=g*d+f1;
      vec3 c22 = fractal(p.xy);
        a=30.;
        p=mod(p+c22-a,a*2.)-a;
        s=2.;
        for(int i=0;i++<8;){
            p=.5-abs(p);
            p.x<p.z?p=p.zyx:p;
            p.z<p.y?p=p.xzy:p;
            s*=e=1.7+sin(iTime*.1)*.1;
            p=abs(p)*e-
                vec3(
                    5.*3.,
                    120,
                    8.*5.
                 )*c22;
         }
         g+=e=length(p.yzzz)/s;
    }
}
